
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbea_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbea", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.300849918795199e+00, -4.218994614263702e+00, -4.104388576397612e+00, -3.945824119396411e+00, -3.730160994941111e+00, -3.443954122697642e+00, -3.077226307716777e+00, -2.630043496742295e+00, -2.120341898148765e+00, -1.584375392030763e+00, -1.063171722100420e+00, -7.066849459210867e-01, -6.019548728976404e-01, -5.002281003886916e-01, -3.667932995895307e-01, -2.353439802390027e-01, -1.255396130768585e-01, -4.740112194933764e-02, -1.068676632359749e-02, -1.214635037716959e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


